// AI quiz for AI Virtual Classroom: the teacher turns the slides (PDF or PowerPoint) into a quiz in seconds,
// launches it for the class, and watches the results live. Learners get a rich, animated quiz with sound.
// Question types: multiple choice, true or false, matching, category sort, ordering and tap the cards.
// Generated by LMS Labs (included in the class price); the Moodle server calls LMS Labs, so the
// site's API key never reaches the browser.

let X = null; // shared helpers from meet.js: {h, icon, toast, send, S, C, W, isMod, sleep}

export const TYPES = [
  { id: 'mcq', name: 'Multiple choice', hint: 'Pick the one right answer' },
  { id: 'truefalse', name: 'True or false', hint: 'Quick check of key facts' },
  { id: 'matching', name: 'Matching', hint: 'Pair terms with meanings' },
  { id: 'categorysort', name: 'Category sort', hint: 'Sort items into groups' },
  { id: 'ordering', name: 'Ordering', hint: 'Put steps in order' },
  { id: 'tapcard', name: 'Tap the cards', hint: 'Find every right card' },
];
const PRICE = { base: 2, voice: 3 };
// Teacher stamps for the quiz wall (never red: green for right, warm colours for praise).
// A quiz title from pasted text: its first few words. And a short word count for under the box.
const pasteTitle = (t) => { const w = String(t || '').replace(/\s+/g, ' ').trim().split(' ').slice(0, 6).join(' ').replace(/[.,;:!?]+$/, ''); return w ? w[0].toUpperCase() + w.slice(1) + (String(t).trim().split(/\s+/).length > 6 ? '…' : '') : 'Quiz'; };
const pasteCount = (t) => { const n = String(t || '').trim() ? String(t).trim().split(/\s+/).length : 0; return n ? `${n.toLocaleString()} words` : 'Up to about 9,000 words'; };
// A friendly quiz title from a file name: "leading-teams.pptx" -> "Leading teams".
const nice = (n) => { const t = String(n || 'Quiz').replace(/\.[a-z0-9]{2,5}$/i, '').replace(/[-_]+/g, ' ').replace(/\s+/g, ' ').trim(); return t ? t[0].toUpperCase() + t.slice(1) : 'Quiz'; };
const STAMPS = {
  tick: { e: '✅', label: 'Green tick' },
  smile: { e: '😊', label: 'Smiley face' },
  star: { e: '⭐', label: 'Gold star' },
  clap: { e: '👏', label: 'Well done' },
  hundred: { e: '💯', label: '100%' },
  heart: { e: '💜', label: 'Love it' },
};

export function init(helpers) {
  X = helpers;
  return Quiz;
}

// ------------------------------------------------------------------ sound (synthesised, no files)
const Sound = {
  ctx: null,
  on: true,
  ac() {
    if (!this.ctx) this.ctx = new (window.AudioContext || window.webkitAudioContext)();
    if (this.ctx.state === 'suspended') this.ctx.resume();
    return this.ctx;
  },
  note(f, t0, dur, type = 'sine', vol = 0.18) {
    const c = this.ac();
    const o = c.createOscillator();
    const g = c.createGain();
    o.type = type;
    o.frequency.setValueAtTime(f, c.currentTime + t0);
    g.gain.setValueAtTime(0.0001, c.currentTime + t0);
    g.gain.exponentialRampToValueAtTime(vol, c.currentTime + t0 + 0.015);
    g.gain.exponentialRampToValueAtTime(0.0001, c.currentTime + t0 + dur);
    o.connect(g).connect(c.destination);
    o.start(c.currentTime + t0);
    o.stop(c.currentTime + t0 + dur + 0.05);
  },
  play(kind) {
    if (!this.on) return;
    try {
      if (kind === 'tap') this.note(880, 0, 0.06, 'triangle', 0.08);
      else if (kind === 'pick') this.note(660, 0, 0.08, 'triangle', 0.1);
      else if (kind === 'right') [523, 659, 784, 1047].forEach((f, i) => { this.note(f, i * 0.07, 0.35, 'triangle', 0.16); this.note(f * 2, i * 0.07 + 0.02, 0.2, 'sine', 0.05); });
      else if (kind === 'again') { this.note(392, 0, 0.18, 'sine', 0.14); this.note(330, 0.14, 0.28, 'sine', 0.14); }
      else if (kind === 'reveal') { this.note(440, 0, 0.2, 'sine', 0.1); this.note(392, 0.15, 0.3, 'sine', 0.1); }
      else if (kind === 'whoosh') {
        const c = this.ac();
        const n = c.createBufferSource();
        const b = c.createBuffer(1, c.sampleRate * 0.35, c.sampleRate);
        const d = b.getChannelData(0);
        for (let i = 0; i < d.length; i++) d[i] = (Math.random() * 2 - 1) * Math.sin((Math.PI * i) / d.length) ** 2 * 0.25;
        const f = c.createBiquadFilter();
        f.type = 'bandpass';
        f.frequency.setValueAtTime(600, c.currentTime);
        f.frequency.exponentialRampToValueAtTime(2400, c.currentTime + 0.3);
        n.buffer = b;
        n.connect(f).connect(c.destination);
        n.start();
      } else if (kind === 'fanfare') [523, 659, 784, 1047, 784, 1047, 1319].forEach((f, i) => this.note(f, i * 0.11, i === 6 ? 0.8 : 0.22, 'triangle', 0.15));
    } catch (e) { /* audio blocked */ }
  },
};

// ------------------------------------------------------------------ confetti (canvas, short burst)
function confetti(host, n = 90) {
  const cv = X.h('canvas', { class: 'qz-confetti' });
  host.append(cv);
  const r = host.getBoundingClientRect();
  cv.width = r.width;
  cv.height = r.height;
  const ctx = cv.getContext('2d');
  const cols = ['#7f10f9', '#c6007f', '#24c45e', '#0e88ff', '#f78e08', '#ffd23f'];
  const ps = Array.from({ length: n }, () => ({
    x: r.width / 2 + (Math.random() - 0.5) * 80, y: r.height * 0.45, vx: (Math.random() - 0.5) * 14, vy: -Math.random() * 13 - 4,
    s: 5 + Math.random() * 7, c: cols[(Math.random() * cols.length) | 0], a: Math.random() * 6, va: (Math.random() - 0.5) * 0.4,
  }));
  let t = 0;
  const tick = () => {
    ctx.clearRect(0, 0, cv.width, cv.height);
    for (const p of ps) {
      p.vy += 0.35;
      p.x += p.vx;
      p.y += p.vy;
      p.a += p.va;
      ctx.save();
      ctx.translate(p.x, p.y);
      ctx.rotate(p.a);
      ctx.fillStyle = p.c;
      ctx.globalAlpha = Math.max(0, 1 - t / 90);
      ctx.fillRect(-p.s / 2, -p.s / 4, p.s, p.s / 2);
      ctx.restore();
    }
    if (++t < 95) requestAnimationFrame(tick);
    else cv.remove();
  };
  tick();
}

const shuffle = (a) => { const b = a.slice(); for (let i = b.length - 1; i > 0; i--) { const j = (Math.random() * (i + 1)) | 0; [b[i], b[j]] = [b[j], b[i]]; } return b; };
const typeName = (id) => (TYPES.find((t) => t.id === id) || {}).name || id;

// ------------------------------------------------------------------ text from the slides
async function textFromPres(pres, Slides) {
  const d = await Slides.doc(pres);
  if (d.pdf) {
    const parts = [];
    for (let i = 1; i <= d.pdf.numPages && i <= 200; i++) {
      const tc = await (await d.pdf.getPage(i)).getTextContent();
      parts.push(`[Slide ${i}] ` + tc.items.map((x) => x.str).join(' '));
    }
    return parts.join('\n');
  }
  if (d.show) {
    const svg = await (await fetch(d.show)).text();
    return textFromSvg(svg);
  }
  return '';
}
function textFromSvg(svg) {
  const doc = new DOMParser().parseFromString(svg, 'image/svg+xml');
  const slides = [...doc.querySelectorAll('g.Slide')];
  return slides.map((g, i) => `[Slide ${i + 1}] ` + g.textContent.replace(/\s+/g, ' ').trim()).filter((t) => t.length > 12).join('\n');
}
async function textFromFile(file, Slides) {
  if (/\.pdf$/i.test(file.name) || file.type === 'application/pdf') {
    const lib = await Slides.lib();
    const pdf = await lib.getDocument({ data: await file.arrayBuffer() }).promise;
    return textFromPres({ key: 'local' }, { doc: async () => ({ pdf }) });
  }
  if (/\.(pptx?|ppsx?|pptm|odp|key|docx?|odt|rtf|txt|xlsx?|ods|csv)$/i.test(file.name)) {
    const fd = new FormData();
    fd.append('file', file);
    fd.append('sesskey', X.C.sesskey);
    const r = await fetch(X.C.slidesUrl, { method: 'POST', body: fd, credentials: 'same-origin' });
    if (!r.ok) throw new Error((await r.json().catch(() => ({}))).error || 'Could not read the presentation');
    if (r.headers.get('X-LiveLab-Type') === 'show') return textFromSvg(await r.text());
    const lib = await Slides.lib();
    const pdf = await lib.getDocument({ data: await r.arrayBuffer() }).promise;
    return textFromPres({ key: 'local' }, { doc: async () => ({ pdf }) });
  }
  throw new Error('Choose a PowerPoint, PDF, Word or Excel file.');
}

