      if (text.replace(/\[Slide \d+\]/g, '').trim().length < 80) throw new Error('These slides have too little text to make questions from. Try a file with more words on the slides.');
      const r = await fetch(C.quizUrl, {
        method: 'POST', credentials: 'same-origin', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ sesskey: C.sesskey, title: st.title || 'Quiz', text: text.slice(0, 60000), count: st.count, types: [...st.types], voice: st.voice }),
      });
      const j = await r.json().catch(() => ({}));
